CREATE     PROCEDURE [synapse_fo].[usp_Update_PROJTABLE]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:30:49
	Description: Update stored procedure for PROJTABLE from synapse finops datalake to BI
*/
BEGIN
	UPDATE tgt SET 
		tgt.[ALERTTIMEFRAMEWEEKS] = stg.[ALERTTIMEFRAMEWEEKS],
		tgt.[ALTERNATEBUDGETPROJECT] = stg.[ALTERNATEBUDGETPROJECT],
		tgt.[ASSETID] = stg.[ASSETID],
		tgt.[BANKDOCUMENTTYPE] = stg.[BANKDOCUMENTTYPE],
		tgt.[CERTIFIEDPAYROLL] = stg.[CERTIFIEDPAYROLL],
		tgt.[CHECKBUDGET] = stg.[CHECKBUDGET],
		tgt.[COMPLETESCHEDULED] = stg.[COMPLETESCHEDULED],
		tgt.[CONTRACTAMENDMENT_SA] = stg.[CONTRACTAMENDMENT_SA],
		tgt.[CONTRACTDATE_SA] = stg.[CONTRACTDATE_SA],
		tgt.[CONTRACTPERIOD_SA] = stg.[CONTRACTPERIOD_SA],
		tgt.[CONTRACTVALUE_SA] = stg.[CONTRACTVALUE_SA],
		tgt.[CREATED] = stg.[CREATED],
		tgt.[CUSTACCOUNT] = stg.[CUSTACCOUNT],
		tgt.[DATAAREAID] = stg.[DATAAREAID],
		tgt.[DataLakeModified_DateTime] = stg.[DataLakeModified_DateTime],
		tgt.[DEFAULTDIMENSION] = stg.[DEFAULTDIMENSION],
		tgt.[DEFAULTFUNDINGSOURCE] = stg.[DEFAULTFUNDINGSOURCE],
		tgt.[DELIVERYLOCATION] = stg.[DELIVERYLOCATION],
		tgt.[DESCRIPTION] = stg.[DESCRIPTION],
		tgt.[DLVNAME] = stg.[DLVNAME],
		tgt.[EMAIL] = stg.[EMAIL],
		tgt.[ENDDATE] = stg.[ENDDATE],
		tgt.[EXTENSIONDATE] = stg.[EXTENSIONDATE],
		--tgt.[FileName] = stg.[FileName],
		tgt.[FORMAT] = stg.[FORMAT],
		tgt.[HEADER] = stg.[HEADER],
		tgt.[JOBID] = stg.[JOBID],
		tgt.[JOBPAYTYPE] = stg.[JOBPAYTYPE],
		tgt.[LastProcessedChange_DateTime] = stg.[LastProcessedChange_DateTime],
		--tgt.[LSN] = stg.[LSN],
		tgt.[MINTIMEINCREMENT] = stg.[MINTIMEINCREMENT],
		tgt.[MODIFIEDDATETIME] = stg.[MODIFIEDDATETIME],
		tgt.[NAME] = stg.[NAME],
		tgt.[OCIP] = stg.[OCIP],
		tgt.[OCIPGL] = stg.[OCIPGL],
		tgt.[PARENTID] = stg.[PARENTID],
		tgt.[PARTITION] = stg.[PARTITION],
		tgt.[PROJBUDGETARYCONTROLON] = stg.[PROJBUDGETARYCONTROLON],
		tgt.[PROJBUDGETINTERVAL] = stg.[PROJBUDGETINTERVAL],
		tgt.[PROJBUDGETMANAGEMENT] = stg.[PROJBUDGETMANAGEMENT],
		tgt.[PROJBUDGETOVERRUNOPTION] = stg.[PROJBUDGETOVERRUNOPTION],
		tgt.[PROJCARRYFORWARDNEGATIVEBUDGET] = stg.[PROJCARRYFORWARDNEGATIVEBUDGET],
		tgt.[PROJCARRYFORWARDREMAININGBUDGET] = stg.[PROJCARRYFORWARDREMAININGBUDGET],
		tgt.[PROJDATASOURCE] = stg.[PROJDATASOURCE],
		tgt.[PROJECTEDENDDATE] = stg.[PROJECTEDENDDATE],
		tgt.[PROJECTEDSTARTDATE] = stg.[PROJECTEDSTARTDATE],
		tgt.[PROJGROUPID] = stg.[PROJGROUPID],
		tgt.[PROJID] = stg.[PROJID],
		tgt.[PROJINVOICEPROJID] = stg.[PROJINVOICEPROJID],
		tgt.[PROJLEDGERPOSTING] = stg.[PROJLEDGERPOSTING],
		tgt.[PROJLINEPROPERTYSEARCH] = stg.[PROJLINEPROPERTYSEARCH],
		tgt.[PROJPRICEGROUP] = stg.[PROJPRICEGROUP],
		tgt.[PSADOINVOICECOST] = stg.[PSADOINVOICECOST],
		tgt.[PSAFORECASTMODELID] = stg.[PSAFORECASTMODELID],
		tgt.[PSAFORECASTMODELIDEXTERNAL] = stg.[PSAFORECASTMODELIDEXTERNAL],
		tgt.[PSAINVOICEMETHOD] = stg.[PSAINVOICEMETHOD],
		tgt.[PSAPROJSTATUS] = stg.[PSAPROJSTATUS],
		tgt.[PSARESSCHEDSTATUS] = stg.[PSARESSCHEDSTATUS],
		tgt.[PSASCHEDCALENDARID] = stg.[PSASCHEDCALENDARID],
		tgt.[PSASCHEDDURATION] = stg.[PSASCHEDDURATION],
		tgt.[PSASCHEDEFFORT] = stg.[PSASCHEDEFFORT],
		tgt.[PSASCHEDENDDATE] = stg.[PSASCHEDENDDATE],
		tgt.[PSASCHEDFROMTIME] = stg.[PSASCHEDFROMTIME],
		tgt.[PSASCHEDIGNORECALENDAR] = stg.[PSASCHEDIGNORECALENDAR],
