		tgt.[PSASCHEDSTARTDATE] = stg.[PSASCHEDSTARTDATE],
		tgt.[PSASCHEDTOTIME] = stg.[PSASCHEDTOTIME],
		tgt.[PSASCHEDUSEDURATION] = stg.[PSASCHEDUSEDURATION],
		tgt.[RECID] = stg.[RECID],
		tgt.[RECVERSION] = stg.[RECVERSION],
		tgt.[REQUIREACTIVITYEXPENSEFORECAST] = stg.[REQUIREACTIVITYEXPENSEFORECAST],
		tgt.[REQUIREACTIVITYEXPENSETRX] = stg.[REQUIREACTIVITYEXPENSETRX],
		tgt.[REQUIREACTIVITYHOURFORECAST] = stg.[REQUIREACTIVITYHOURFORECAST],
		tgt.[REQUIREACTIVITYHOURTRX] = stg.[REQUIREACTIVITYHOURTRX],
		tgt.[REQUIREACTIVITYITEMFORECAST] = stg.[REQUIREACTIVITYITEMFORECAST],
		tgt.[REQUIREACTIVITYITEMTRX] = stg.[REQUIREACTIVITYITEMTRX],
		tgt.[SORTINGID] = stg.[SORTINGID],
		tgt.[SORTINGID2_] = stg.[SORTINGID2_],
		tgt.[SORTINGID3_] = stg.[SORTINGID3_],
		tgt.[STARTDATE] = stg.[STARTDATE],
		tgt.[STATUS] = stg.[STATUS],
		tgt.[SUBJECT_SA] = stg.[SUBJECT_SA],
		--tgt.[SysRowId] = stg.[SysRowId],
		tgt.[TAXGROUPID] = stg.[TAXGROUPID],
		tgt.[TEMPLATE] = stg.[TEMPLATE],
		tgt.[TEMPLATEAPPLIED] = stg.[TEMPLATEAPPLIED],
		tgt.[TIMEPOSTDETAILSUMMARY] = stg.[TIMEPOSTDETAILSUMMARY],
		tgt.[TYPE] = stg.[TYPE],
		tgt.[USEALTERNATEPROJECT] = stg.[USEALTERNATEPROJECT],
		tgt.[USEBUDGETING] = stg.[USEBUDGETING],
		tgt.[VALIDATEPROJCATEGORY] = stg.[VALIDATEPROJCATEGORY],
		tgt.[WIPPROJECT] = stg.[WIPPROJECT],
		tgt.[WORKERPSAARCHITECT] = stg.[WORKERPSAARCHITECT],
		tgt.[WORKERRESPONSIBLE] = stg.[WORKERRESPONSIBLE],
		tgt.[WORKERRESPONSIBLEFINANCIAL] = stg.[WORKERRESPONSIBLEFINANCIAL],
		tgt.[WORKERRESPONSIBLESALES] = stg.[WORKERRESPONSIBLESALES]
	 FROM [synapse_fo].[PROJTABLE] tgt
		INNER JOIN [staging_fo].[PROJTABLE] stg
			ON  stg.[DataAreaId] = tgt.[DataAreaId] 
			AND stg.[PARTITION] = tgt.[PARTITION] 
			AND stg.[ProjId] = tgt.[ProjId] 
		
END
